/**
 * A text file based implementation of a {@link ViolationStore}.<br>
 * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
 * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.
 * <p>
 * The store can be configured through the following properties:
 * <pre><code>
 * default.path=...               # string: the path of the folder where violation files will be stored
 * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
 * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
 * default.fileNames=...          # random, description, or a strategy class name
 * default.integrity=...          # ignore, repair, or fail
 * </code></pre>
 */
@PublicAPI(usage = ACCESS)
public final class TextFileBasedViolationStore implements ViolationStore {
    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);

    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
    private static final Pattern DESCRIPTION_WORD_PATTERN = Pattern.compile("(?<![A-Za-z0-9])([A-Za-z0-9]{4,120})(?![A-Za-z0-9])");
    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
    private static final String STORE_PATH_DEFAULT = "archunit_store";
    private static final String STORED_RULES_FILE_NAME = "stored.rules";
    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
    private static final String FILE_NAMES_DEFAULT = "random";
    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
    private static final String INTEGRITY_DEFAULT = "ignore";
    private static final String RANDOM_FILE_NAMES = "random";
    private static final String DESCRIPTION_FILE_NAMES = "description";
    private static final String INTEGRITY_REPAIR = "repair";
    private static final String INTEGRITY_FAIL = "fail";
    private static final String INTEGRITY_IGNORE = "ignore";

    /* A save and an integrity check must not observe one another halfway through. */
    private static final ConcurrentHashMap<String, Object> STORE_LOCKS = new ConcurrentHashMap<>();

    private final RuleViolationFileNameStrategy constructorStrategy;

    private boolean storeCreationAllowed;
    private boolean storeUpdateAllowed;
    private IntegrityMode integrityMode;
    private FileNameMode fileNameMode;
    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
    private Path storeFolder;
    private Path storedRulesFile;
    private Object storeLock;

    /**
     * Creates a standard {@link TextFileBasedViolationStore} that names rule violation files by random {@link UUID}s.
     *
     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
     */
    public TextFileBasedViolationStore() {
        constructorStrategy = null;
        ruleViolationFileNameStrategy = description -> UUID.randomUUID().toString();
    }

    /**
     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming.
     *
     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
     */
    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
        if (ruleViolationFileNameStrategy == null) {
            throw new NullPointerException("ruleViolationFileNameStrategy");
        }
        constructorStrategy = ruleViolationFileNameStrategy;
        this.ruleViolationFileNameStrategy = ruleViolationFileNameStrategy;
    }

    @Override
    public void initialize(Properties properties) {
        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
        integrityMode = IntegrityMode.from(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
        fileNameMode = configureFileNameStrategy(properties);
        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Integrity repair requires %s.%s=true",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        try {
            storeFolder = Paths.get(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT)).toAbsolutePath().normalize();
            storedRulesFile = storeFolder.resolve(STORED_RULES_FILE_NAME);
            storeLock = STORE_LOCKS.computeIfAbsent(storeFolder.toFile().getCanonicalPath(), ignored -> new Object());
        } catch (IOException | InvalidPathException e) {
            throw new StoreInitializationFailedException(e);
        }

        synchronized (storeLock) {
            prepareStore();
            Properties storedRules = loadStoredRules();
            if (integrityMode != IntegrityMode.IGNORE) {
                IntegrityState integrity = inspect(storedRules);
                if (integrityMode == IntegrityMode.FAIL) {
                    failIfNecessary(integrity);
                } else {
                    repair(integrity, storedRules);
                }
            }
        }
        log.trace("Initialized {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesFile);
    }

    private FileNameMode configureFileNameStrategy(Properties properties) {
        if (constructorStrategy != null) {
            if (hasProperty(properties, FILE_NAMES_PROPERTY_NAME)) {
                throw new StoreInitializationFailedException(String.format(
                        "Cannot configure %s when a rule file name strategy was supplied to the constructor",
                        FILE_NAMES_PROPERTY_NAME));
            }
            ruleViolationFileNameStrategy = constructorStrategy;
            return FileNameMode.CUSTOM;
        }

        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_DEFAULT);
        if (RANDOM_FILE_NAMES.equals(configured)) {
            ruleViolationFileNameStrategy = description -> UUID.randomUUID().toString();
            return FileNameMode.RANDOM;
        }
        if (DESCRIPTION_FILE_NAMES.equals(configured)) {
            ruleViolationFileNameStrategy = TextFileBasedViolationStore::fileNameFromDescription;
            return FileNameMode.DESCRIPTION;
        }

        try {
            Class<?> strategyClass = Class.forName(configured);
            Object strategy = strategyClass.getConstructor().newInstance();
            if (!(strategy instanceof RuleViolationFileNameStrategy)) {
                throw new IllegalArgumentException("does not implement " + RuleViolationFileNameStrategy.class.getName());
            }
            ruleViolationFileNameStrategy = (RuleViolationFileNameStrategy) strategy;
            return FileNameMode.CUSTOM;
        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException |
                 InvocationTargetException | IllegalArgumentException | LinkageError e) {
            throw new StoreInitializationFailedException(String.format(
                    "Cannot instantiate %s strategy '%s' with a public no-argument constructor",
                    FILE_NAMES_PROPERTY_NAME, configured), e);
        }
    }

    private boolean hasProperty(Properties properties, String name) {
        Enumeration<?> propertyNames = properties.propertyNames();
        while (propertyNames.hasMoreElements()) {
            if (name.equals(propertyNames.nextElement())) {
                return true;
            }
        }
        return false;
    }

    private void prepareStore() {
        boolean indexExists = Files.exists(storedRulesFile, LinkOption.NOFOLLOW_LINKS);
        if (!indexExists && (!storeCreationAllowed || integrityMode == IntegrityMode.FAIL)) {
            if (integrityMode == IntegrityMode.FAIL) {
                throw new StoreInitializationFailedException(String.format(
                        "Integrity check cannot initialize without an existing %s", STORED_RULES_FILE_NAME));
            }
            }
            throw new StoreInitializationFailedException(String.format(
                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
        }

        try {
            if (!Files.exists(storeFolder, LinkOption.NOFOLLOW_LINKS)) {
                Files.createDirectories(storeFolder);
            }
            if (!Files.isDirectory(storeFolder)) {
                throw new StoreInitializationFailedException(String.format("Store path is not a folder: %s", storeFolder));
            }
            if (!Files.exists(storedRulesFile, LinkOption.NOFOLLOW_LINKS)) {
                Files.createFile(storedRulesFile);
            }
            if (!Files.isRegularFile(storedRulesFile, LinkOption.NOFOLLOW_LINKS)) {
                throw new StoreInitializationFailedException(String.format(
                        "The %s must be a regular file directly in the store folder", STORED_RULES_FILE_NAME));
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private Properties loadStoredRules() {
        Properties result = new Properties();
        try (InputStream inputStream = Files.newInputStream(storedRulesFile)) {
            result.load(inputStream);
            return result;
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private IntegrityState inspect(Properties storedRules) {
        List<RuleEntry> entries = new ArrayList<>();
        for (String description : storedRules.stringPropertyNames()) {
            RuleEntry entry = new RuleEntry(description, storedRules.getProperty(description));
            entry.path = pathForName(entry.name);
            if (entry.path == null) {
                entry.broken = true;
            } else {
                entry.target = regularFileDirectlyInFolder(entry.path);
                entry.broken = entry.target == null;
                if (!entry.broken) {
                    entry.resolved = hasNoViolations(entry.target);
                }
            }
            entry.derivedName = deriveNameForIntegrity(entry.description, entry.name);
            entry.misplaced = entry.derivedName != null && !entry.derivedName.equals(entry.name);
            entries.add(entry);
        }

        markShared(entries);
        markColliding(entries);
        for (RuleEntry entry : entries) {
            if (entry.misplaced && !entry.shared) {
                entry.occupied = isOccupied(entry, entries);
            }
        }
        List<Path> unownedFiles = findUnownedFiles(entries);
        return new IntegrityState(entries, unownedFiles);
    }

    private String deriveNameForIntegrity(String description, String currentName) {
        // A random name has no reproducible expected value. It is nevertheless a valid
        // name for an existing entry and must not make every random store look corrupt.
        if (fileNameMode == FileNameMode.RANDOM) {
            return currentName;
        }
        return fileNameNeeded(description, true);
    }

    private String fileNameNeeded(String description, boolean initialization) {
        String result;
        try {
            result = ruleViolationFileNameStrategy.createRuleFileName(description);
        } catch (RuntimeException e) {
            if (initialization) {
                throw new StoreInitializationFailedException(e);
            }
            throw new StoreUpdateFailedException(e);
        }
        if (result == null || result.isEmpty()) {
            String message = "Rule file name strategy yielded no name for rule description '" + description + "'";
            if (initialization) {
                throw new StoreInitializationFailedException(message);
            }
            throw new StoreUpdateFailedException(message);
        }
        return result;
    }

    private void markShared(List<RuleEntry> entries) {
        for (int i = 0; i < entries.size(); i++) {
            RuleEntry left = entries.get(i);
            for (int j = i + 1; j < entries.size(); j++) {
                RuleEntry right = entries.get(j);
                if (Objects.equals(left.name, right.name) || sameFile(left.path, right.path)) {
                    left.shared = true;
                    right.shared = true;
                }
            }
        }
    }

    private boolean sameFile(Path left, Path right) {
        if (left == null || right == null) {
            return false;
        }
        try {
            return Files.isSameFile(left, right);
        } catch (IOException | SecurityException e) {
            return false;
        }
    }

    private void markColliding(List<RuleEntry> entries) {
        Map<String, List<RuleEntry>> byDerivedName = new HashMap<>();
        for (RuleEntry entry : entries) {
            if (entry.derivedName != null) {
                byDerivedName.computeIfAbsent(entry.derivedName, ignored -> new ArrayList<>()).add(entry);
            }
        }
        for (List<RuleEntry> collidingEntries : byDerivedName.values()) {
            if (collidingEntries.size() > 1) {
                for (RuleEntry entry : collidingEntries) {
                    entry.colliding = true;
                }
            }
        }
    }

    private boolean isOccupied(RuleEntry entry, List<RuleEntry> entries) {
        for (RuleEntry other : entries) {
            if (other != entry && entry.derivedName.equals(other.name)) {
                return true;
            }
        }
        Path derivedPath = pathForName(entry.derivedName);
        if (derivedPath == null || !canReachDirectFolder(derivedPath)) {
            return true;
        }
        return Files.exists(derivedPath, LinkOption.NOFOLLOW_LINKS);
    }

    private List<Path> findUnownedFiles(List<RuleEntry> entries) {
        List<Path> result = new ArrayList<>();
        try (DirectoryStream<Path> children = Files.newDirectoryStream(storeFolder)) {
            for (Path child : children) {
                if (sameFile(child, storedRulesFile) || !Files.isRegularFile(child, LinkOption.NOFOLLOW_LINKS)) {
                    continue;
                }
                boolean owned = false;
                for (RuleEntry entry : entries) {
                    if (sameFile(entry.path, child)) {
                        owned = true;
                        break;
                    }
                }
                if (!owned) {
                    result.add(child);
                }
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
        result.sort(Comparator.comparing(path -> path.getFileName().toString()));
        return result;
    }

    private void failIfNecessary(IntegrityState integrity) {
        if (integrity.isClean()) {
            return;
        }
        StringBuilder message = new StringBuilder("Violation store integrity check failed at ")
                .append(storeFolder)
                .append(" (default.allowStoreUpdate=")
                .append(storeUpdateAllowed)
                .append("):");
        appendEntries(message, "broken", integrity.entriesMatching(entry -> entry.broken));
        appendEntries(message, "resolved", integrity.entriesMatching(entry -> entry.resolved));
        appendEntries(message, "shared", integrity.entriesMatching(entry -> entry.shared));
        appendEntries(message, "misplaced", integrity.entriesMatching(entry -> entry.misplaced));
        appendEntries(message, "colliding", integrity.entriesMatching(entry -> entry.colliding));
        appendEntries(message, "occupied", integrity.entriesMatching(entry -> entry.occupied));
        if (!integrity.unownedFiles.isEmpty()) {
            message.append(" unowned files: ");
            for (int i = 0; i < integrity.unownedFiles.size(); i++) {
                if (i > 0) {
                    message.append(", ");
                }
                message.append(integrity.unownedFiles.get(i).getFileName());
            }
            message.append(';');
        }
        throw new StoreInitializationFailedException(message.toString());
    }

    private void appendEntries(StringBuilder message, String condition, List<RuleEntry> entries) {
        if (entries.isEmpty()) {
            return;
        }
        entries.sort(Comparator.comparing(entry -> entry.description));
        message.append(' ').append(condition).append(" entries: ");
        for (int i = 0; i < entries.size(); i++) {
            if (i > 0) {
                message.append(", ");
            }
            RuleEntry entry = entries.get(i);
            message.append('[').append(entry.description).append(" -> ").append(entry.name).append(']');
        }
        message.append(';');
    }

    private void repair(IntegrityState integrity, Properties storedRules) {
        boolean changed = false;

        for (RuleEntry entry : integrity.entries) {
            if (entry.shared) {
                continue;
            }
            if (entry.broken) {
                storedRules.remove(entry.description);
                changed = true;
            } else if (entry.resolved) {
                deleteResolvedEntryFile(entry, true);
                storedRules.remove(entry.description);
                changed = true;
            }
        }

        for (RuleEntry entry : integrity.entries) {
            if (entry.shared || entry.broken || entry.resolved || entry.colliding || entry.occupied || !entry.misplaced) {
                continue;
            }
            Path derivedPath = pathForName(entry.derivedName);
            try {
                Files.move(entry.target, derivedPath);
            } catch (IOException e) {
                throw new StoreInitializationFailedException(String.format(
                        "Cannot move violation file for rule '%s' to '%s'", entry.description, entry.derivedName), e);
            }
            storedRules.setProperty(entry.description, entry.derivedName);
            changed = true;
        }

        if (changed) {
            writeStoredRules(storedRules);
        }
    }

    private void deleteResolvedEntryFile(RuleEntry entry, boolean initialization) {
        if (sameFile(entry.target, storedRulesFile)) {
            // A corrupt entry must never be allowed to delete the index itself.
            return;
        }
        try {
            if (entry.path != null && Files.isSymbolicLink(entry.path)) {
                Files.deleteIfExists(entry.target);
                Files.deleteIfExists(entry.path);
            } else if (entry.path != null) {
                Files.deleteIfExists(entry.path);
            }
        } catch (IOException e) {
            if (initialization) {
                throw new StoreInitializationFailedException(String.format(
                        "Cannot delete resolved violation file '%s'", entry.name), e);
            }
            throw new StoreUpdateFailedException(e);
        }
    }

    @Override
    public boolean contains(ArchRule rule) {
        synchronized (storeLock) {
            return loadStoredRules().containsKey(rule.getDescription());
        }
    }

